import{n as e,o as t,r as n}from"./app-C9M3NSvs.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/web3/smart/polkadot/","title":"Polkadot(DOT)","lang":"zh-CN","frontmatter":{"description":"Polkadot(DOT) Polkadot 是一个多链区块链协议，旨在实现区块链网络的互操作性和可扩展性，Substrate 开发而成。 2016 年 概念提出：Polkadot 的创始人 Gavin Wood（以太坊联合创始人之一）提出了 Polkadot 的概念，旨在通过一个多链框架来实现区块链互操作性和可扩展性。 2017 年 白皮书发布：Po...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Polkadot(DOT)\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/web3/smart/polkadot/"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"Polkadot(DOT)"}],["meta",{"property":"og:description","content":"Polkadot(DOT) Polkadot 是一个多链区块链协议，旨在实现区块链网络的互操作性和可扩展性，Substrate 开发而成。 2016 年 概念提出：Polkadot 的创始人 Gavin Wood（以太坊联合创始人之一）提出了 Polkadot 的概念，旨在通过一个多链框架来实现区块链互操作性和可扩展性。 2017 年 白皮书发布：Po..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.68,"words":503},"filePathRelative":"web3/smart/polkadot/README.md","autoDesc":true}`),a={name:`README.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h1 id="polkadot-dot" tabindex="-1"><a class="header-anchor" href="#polkadot-dot"><span>Polkadot(DOT)</span></a></h1><p><a href="https://polkadot.network/" target="_blank" rel="noopener noreferrer">Polkadot</a> 是一个多链区块链协议，旨在实现区块链网络的互操作性和可扩展性，Substrate 开发而成。</p><h2 id="_2016-年" tabindex="-1"><a class="header-anchor" href="#_2016-年"><span>2016 年</span></a></h2><ul><li><strong>概念提出</strong>：Polkadot 的创始人 Gavin Wood（以太坊联合创始人之一）提出了 Polkadot 的概念，旨在通过一个多链框架来实现区块链互操作性和可扩展性。</li></ul><h2 id="_2017-年" tabindex="-1"><a class="header-anchor" href="#_2017-年"><span>2017 年</span></a></h2><ul><li><strong>白皮书发布</strong>：Polkadot 白皮书发布，详细介绍了其技术架构和愿景。</li><li><strong>初始代币发行（ICO）</strong>：Polkadot 进行 ICO，筹集了超过 1.4 亿美元的资金，以支持项目开发。</li></ul><h2 id="_2018-年" tabindex="-1"><a class="header-anchor" href="#_2018-年"><span>2018 年</span></a></h2><ul><li><strong>Web3 基金会成立</strong>：Web3 基金会成立，旨在支持和推动 Polkadot 及其生态系统的发展。</li><li><strong>初始开发</strong>：开始进行 Polkadot 的初始开发，专注于实现其关键技术组件。</li></ul><h2 id="_2019-年" tabindex="-1"><a class="header-anchor" href="#_2019-年"><span>2019 年</span></a></h2><ul><li><strong>PoC（概念验证）发布</strong>：Polkadot 发布多个 PoC 版本，测试其基础架构和协议。</li><li><strong>Kusama 网络上线</strong>：Polkadot 的“金丝雀网络” Kusama 上线，为 Polkadot 主网的发布做准备，并提供了一个实验性平台。</li></ul><h2 id="_2020-年" tabindex="-1"><a class="header-anchor" href="#_2020-年"><span>2020 年</span></a></h2><ul><li><strong>主网启动</strong>：Polkadot 主网在 5 月份启动，开始分阶段上线其功能。</li><li><strong>NPoS（提名权益证明）</strong>：Polkadot 引入 NPoS 共识机制，增强网络安全性和去中心化程度。</li><li><strong>链上治理</strong>：Polkadot 实现链上治理，允许持有者参与网络的治理和决策。</li></ul><h2 id="_2021-年" tabindex="-1"><a class="header-anchor" href="#_2021-年"><span>2021 年</span></a></h2><ul><li><strong>平行链（Parachains）竞拍</strong>：Polkadot 开始进行平行链插槽竞拍，项目可以竞标获得平行链插槽，以部署其独立区块链。</li><li><strong>生态系统扩展</strong>：多个项目成功竞标平行链插槽，Polkadot 生态系统迅速扩展，包括 DeFi、NFT、数据隐私等多个领域。</li></ul><h2 id="_2022-年" tabindex="-1"><a class="header-anchor" href="#_2022-年"><span>2022 年</span></a></h2><ul><li><strong>跨链互操作性</strong>：Polkadot 加强其跨链互操作性功能，支持更多区块链之间的通信和资产转移。</li><li><strong>持续发展</strong>：Polkadot 继续推动其技术进步和生态系统建设，吸引更多开发者和项目参与。</li></ul>`,16)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};